import { type RecordingSample } from "./landmark-db";

export function generateNpzPython(samples: RecordingSample[]): string {
  const words = Array.from(new Set(samples.map((s) => s.word)));
  const wordToIdx = Object.fromEntries(words.map((w, i) => [w, i]));

  const samplesByWord = words.map((w) => samples.filter((s) => s.word === w));
  const maxFrames = 60;
  const nDims = 126;

  const shape = `(${samples.length}, ${maxFrames}, ${nDims})`;

  const lines: string[] = [
    '"""',
    "Auto-generated NumPy dataset builder from SignTutor Data Collection Studio.",
    "Reads JSON recordings and saves train.npz / val.npz / test.npz ready for",
    "python ml/train_word_model.py --source collected --epochs 50",
    "",
    "Usage:",
    "  python build_dataset.py input.json  # builds from that file",
    '  python build_dataset.py             # expects asl-collected-data.json',
    "",
    'Requires: pip install numpy scikit-learn',
    '"""',
    "from __future__ import annotations",
    "",
    "import json",
    "import os",
    "import sys",
    "import numpy as np",
    "from sklearn.model_selection import train_test_split",
    "",
    "",
    "def load_recordings(path: str):",
    "    with open(path) as f:",
    "        return json.load(f)",
    "",
    "",
    "def build_dataset(samples):",
    "    words = sorted({s['word'] for s in samples})",
    "    word_to_idx = {w: i for i, w in enumerate(words)}",
    "    max_frames = 60",
    "    n_dims = 126",
    "    entry_shape = (max_frames, 21, 3)",
    "",
    "    N = len(samples)",
    "    X = np.zeros((N, max_frames, n_dims), dtype=np.float32)",
    "    y = np.zeros(N, dtype=np.int64)",
    "    labels = words",
    "",
    "    def normalize_seq(seq):",
    "        T = seq.shape[0]",
    "        WRIST = 0",
    "        MIDDLE_MCP = 9",
    "        pos = seq - seq[0, WRIST]",
    "        scale = np.hypot(pos[0, MIDDLE_MCP, 0], pos[0, MIDDLE_MCP, 1])",
    "        if scale < 1e-6:",
    "            scale = 1.0",
    "        pos = pos / scale",
    "        vel = np.zeros_like(pos)",
    "        vel[1:] = pos[1:] - pos[:-1]",
    "        flat = np.concatenate([pos.reshape(T, 63), vel.reshape(T, 63)], axis=1)",
    "        out = np.zeros((max_frames, 126), dtype=np.float32)",
    "        T2 = min(T, max_frames)",
    "        out[:T2] = flat[:T2]",
    "        if T < max_frames:",
    "            out[T:] = out[T - 1]",
    "        return out",
    "",
    "    for i, s in enumerate(samples):",
    '        word = s["word"]',
    '        raw = np.array(s["landmarks"], dtype=np.float32)',
    "        if raw.ndim != 3 or raw.shape[1:] != (21, 3):",
    '            print(f\"WARNING: sample {i} shape {raw.shape}, skipping\")',
    "            continue",
    "        y[i] = word_to_idx[word]",
    "        X[i] = normalize_seq(raw)",
    "",
    "    return X, y, labels",
    "",
    "",
    "def stratified_split(X, y, val_ratio=0.10, test_ratio=0.20, seed=42):",
    "    from sklearn.model_selection import train_test_split",
    "    X_tv, X_test, y_tv, y_test = train_test_split(",
    "        X, y, test_size=test_ratio, random_state=seed, stratify=y",
    "    )",
    "    val_adj = val_ratio / (1 - test_ratio)",
    "    X_train, X_val, y_train, y_val = train_test_split(",
    "        X_tv, y_tv, test_size=val_adj, random_state=seed, stratify=y_tv",
    "    )",
    "    return X_train, X_val, X_test, y_train, y_val, y_test",
    "",
    "",
    "def main():",
    "    path = sys.argv[1] if len(sys.argv) > 1 else 'asl-collected-data.json'",
    "    if not os.path.exists(path):",
    '        print(f"ERROR: {path} not found. Export from /research/collect first.")',
    "        sys.exit(1)",
    "",
    '    print("Loading recordings...")',
    "    samples = load_recordings(path)",
    '    print(f"  {len(samples)} samples, {len(set(s[\'word\'] for s in samples))} classes")',
    "",
    "    X, y, labels = build_dataset(samples)",
    "    X_train, X_val, X_test, y_train, y_val, y_test = stratified_split(X, y)",
    "",
    '    os.makedirs("ml/data/cache/word_collected", exist_ok=True)',
    '    np.savez_compressed("ml/data/cache/word_collected/train.npz", X=X_train, y=y_train, labels=np.array(labels))',
    '    np.savez_compressed("ml/data/cache/word_collected/val.npz", X=X_val, y=y_val, labels=np.array(labels))',
    '    np.savez_compressed("ml/data/cache/word_collected/test.npz", X=X_test, y=y_test, labels=np.array(labels))',
    '    with open("ml/data/cache/word_collected/meta.json", "w") as f:',
    "        json.dump({",
    '            "source": "collected",',
    '            "vocab_size": len(labels),',
    '            "words": labels,',
    '            "t_frames": max_frames,',
    '            "feature_dim": 126,',
    '            "n_train": len(y_train),',
    '            "n_val": len(y_val),',
    '            "n_test": len(y_test),',
    '            "augmentation": False,',
    '            "split_ratios": {"train": 0.70, "val": 0.10, "test": 0.20},',
    "        }, f, indent=2)",
    "",
    '    print("Done! Cached to ml/data/cache/word_collected/")',
    '    print("Retrain with:")',
    '    print("  python ml/train_word_model.py --source collected --epochs 80 --patience 10")',
    "",
    "",
    "if __name__ == '__main__':",
    "    main()",
    "",
  ];

  return lines.join("\n");
}
